    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    # Ensure we only process up to n+1 terms or the length of coeffs, whichever is smaller
    length = min(n + 1, len(coeffs))
    for i in range(length):
        coeff = coeffs[i]
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign and absolute coefficient
        sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)

        # Build coefficient part
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            if abs_coeff == 1:
                coeff_str = ''
            else:
                coeff_str = str(abs_coeff)

        # Build variable part
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'

        term = coeff_str + var_str

        # Append sign appropriately
        if not terms:
            # First term: sign only if negative
            if sign == '-':
                terms.append('-' + term)
            else:
                terms.append(term)
        else:
            terms.append(sign + term)

    if not terms:
        return '0'
    return ''.join(terms)

